mapper.select:
select , c.corp_name as tenant_name, c.corp_id as corp_id, a.app_name as app_name, case when a.app_secret is null or a.app_secret = '' then 0 else 1 end as app_secret_ready from ${attCfgTable} t left join ${cfgTable} c on c.id = t.cfgid left join ${appBindTable} a on a.id = t.app_id
and t.type = #{type} and t.row_type = #{rowType} and t.cfgid = #{cfgId}
and t.cfgid in #{cid}
and 1 = 0
order by t.cfgid, t.row_type, t.id

select top 1  from ${attCfgTable} t
where t.type = #{type} and t.cfgid = #{cfgId} and t.row_type = #{rowType} and t.cfg_name = #{cfgName}
order by t.id

mapper.update:
update ${attCfgTable}
set enabled = #{enabled},
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{modifyTime}
where id = #{id}

update ${attCfgTable}
set app_id = #{appId},
    check_state = 0,
    check_msg = '',
    check_time = '',
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{modifyTime}
where id = #{id}

update ${attCfgTable}
set check_state = #{checkState},
    check_msg = #{checkMsg},
    check_time = #{checkTime},
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{modifyTime}
where id = #{id}

update ${attCfgTable}
set last_run_time = #{lastRunTime},
    last_result = #{lastResult},
    last_result_text = #{lastResultText},
    fail_streak = #{failStreak},
    last_log_id = #{lastLogId},
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{modifyTime}
where id = #{id}

mapper.select:
select b.id, b.cfg_id, b.app_name, b.agent_id, b.yx, case when b.app_secret is null or b.app_secret = '' then 0 else 1 end as secret_configured, case when c.corp_secret is null or c.corp_secret = '' then 0 else 1 end as cfg_secret_configured from ${appBindTable} b left join ${cfgTable} c on c.id = b.cfg_id where c.type = #{type}
and b.cfg_id in #{cid}
and 1 = 0
order by b.cfg_id, b.id

select cast(r.id as int) as oa_user_id, r.lastname as name, r.loginid as login_id, r.workcode as work_code, r.status as status, b.x_user_id as wx_user_id, b.bind_state as bind_state, cast(r.departmentid as int) as dept_id, cast(d.subcompanyid1 as int) as sub_id from hrmresource r left join hrmdepartment d on d.id = r.departmentid left join ${userBindTable} b on b.cfg_id = #{cfgId} and b.oa_user_id = r.id where r.status < 4 and (r.loginid is null or r.loginid <> 'sysadmin')
and (
or r.departmentid in #{did}
or d.subcompanyid1 in #{sid}
or r.id in #{uid}
)
and 1 = 0
order by r.id

select cast(b.oa_user_id as int) as oa_user_id, b.x_user_id as wx_user_id, b.bind_state as bind_state from ${userBindTable} b where b.cfg_id = #{cfgId}
and b.oa_user_id in #{uid}
order by b.oa_user_id

select top 1  from ${attLinkTable} k
where k.type = #{type} and k.cfgid = #{cfgid} and k.dir = #{dir} and k.oa_user_id = #{oaUserId}
  and k.sign_date = #{signDate} and k.sign_time = #{signTime} and k.sign_type = #{signType}
  and k.data_type = #{dataType}
order by k.id

select top 1  from ${attLinkTable} k
where k.type = #{type} and k.cfgid = #{cfgid} and k.dir = #{dir} and k.wx_record_id = #{wxRecordId}
order by k.id

select  from ${attLinkTable} k

    and k.type = #{type}
    and k.cfgid = #{cfgid}
    and k.dir = #{dir}
    and k.source = #{source}
    and k.oa_user_id = #{oaUserId}
    and k.sign_date >= #{signFrom}
    and k.sign_date <= #{signTo}

order by k.id
